$('#ai-chat-button').click(function() {
	var disButton = $(this),
		userScalableTag = $("<meta>", {
			name: "viewport",
			id: "meta-no-zoom",
			content: "width=device-width, user-scalable=no"
		});
	$('#botIframe').toggleClass('show-ai-chat hide-ai-chat');
	disButton.toggleClass('close-ai-bot open-ai-bot');
	$('html').toggleClass('ai-chat-open');
	if($(window).width() < 991) {
		$("head").append(userScalableTag);
	}
});

$('.close-ai-bot-moblie').click(function() {
	$('#botIframe').toggleClass('show-ai-chat hide-ai-chat');
	$('#ai-chat-button').toggleClass('close-ai-bot open-ai-bot');
	$('html').toggleClass('ai-chat-open');
	$("head #meta-no-zoom").remove();
});

$('#ai-chat-button').mouseup(function(e) {
	var container = $("#botIframe");
	if($(e.target).parents("#ai-chat-button, .close-ai-bot-moblie").length == 0) {
		container.removeClass('show-ai-chat').addClass('hide-ai-chat');
		$('#ai-chat-button').removeClass('close-ai-bot').addClass('open-ai-bot');
		$('html').removeClass('ai-chat-open');
		$("head").remove(userScalableTag);
		e.preventDefault()
		e.stopPropagation()
	}
});

